// Servidor de eventos (extracto): una sala = un contador y un historial acotado
const e = { id: ++s.seq, tipo, datos };
s.historial.push(e);
if (s.historial.length > BUF) s.historial.shift();   // solo se guardan los últimos BUF
for (const res of s.conexiones) res.write(trama(e));  // difusión a la sala

// Al conectarse un cliente:
const ultimo = req.headers['last-event-id'];          // lo manda el navegador al reconectar
if (ultimo !== undefined) {
  const n = +ultimo;
  const masViejo = s.historial.length ? s.historial[0].id : s.seq + 1;
  if (n < s.seq && n + 1 < masViejo) {
    // faltan eventos que ya no guardamos: no se puede reponer
    res.write(`id: ${s.seq}\nevent: reinicio\ndata: {...}\n\n`);
  } else {
    for (const e of s.historial) if (e.id > n) res.write(trama(e));
  }
}

