create table eventos (
  id    bigserial primary key,
  sala  text  not null,
  tipo  text  not null default 'novedad',
  datos jsonb not null
);
create index on eventos (sala, id);

create function avisar_evento() returns trigger language plpgsql as $$
declare p text := row_to_json(new)::text;
begin
  -- si el evento no entra holgado en el aviso, va solo la dirección (sala e id)
  if length(p) > 7000 then p := json_build_object('sala', new.sala, 'id', new.id)::text; end if;
  perform pg_notify('eventos', p);
  return new;
end $$;
create trigger eventos_avisan after insert on eventos
  for each row execute function avisar_evento();

